    static const FLoadoutTable& Loadout() { return LoadoutStorage; }
    static const FHolderTable& Holder() { return HolderStorage; }
    static const FBagTable& Bag() { return BagStorage; }
    static const FMountTable& Mount() { return MountStorage; }
    static const FClipTable& Clip() { return ClipStorage; }
    static const FPoseTable& Pose() { return PoseStorage; }
    static const FSealTable& Seal() { return SealStorage; }
    static const FBadgeTable& Badge() { return BadgeStorage; }
    static const FKitTable& Kit() { return KitStorage; }

    /**
     * Reads every table from BasePath. Returns false if any of them could not be read.
     *
     * FileExtension defaults to what the recipe told the exporter to write. Pass a different
     * one when the data files were renamed on the way into the package - which they often are,
     * since some platforms only cook what carries an extension they recognise.
     */
